'use strict';
const groups=window.reviewGroups;
const q=new URLSearchParams(location.search);
if(q.get('capture')==='1')document.body.classList.add('capture');
const currentGroup=groups.find(g=>g.id===document.body.dataset.group);
let screen=currentGroup?.screens.find(s=>s[0]===location.hash.slice(1))||currentGroup?.screens[0];
const roles={public:'Chưa đăng nhập',requester:'Nhân viên',technician:'Kỹ thuật viên',manager:'Trưởng phòng IT',admin:'Admin'};
const names={requester:'Nguyễn Phương Lan',technician:'Trần Quốc Bình',manager:'Nguyễn Thu Hà',admin:'Lê Hoàng An'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"></use></svg>`;
const btn=(text,action,kind='',icon='')=>`<button class="btn ${kind}" data-action="${action}">${icon?ico(icon):''}${text}</button>`;
const link=(text,id,kind='')=>`<a class="btn ${kind}" href="${urlFor(id)}">${text}${ico('arrow-right')}</a>`;
function urlFor(id){for(const g of groups){if(g.screens.some(s=>s[0]===id))return `${g.id}.html#${id}`;}return 'index.html';}
const pill=(t,c='')=>`<span class="pill ${c}">${t}</span>`;
const box=(title,body,sub='',action='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;
const banner=(title,text='',kind='')=>`<div class="banner ${kind}">${ico(kind==='amber'?'alert':kind==='green'?'check-circle':'info')}<div><strong>${title}</strong>${text?`<p>${text}</p>`:''}</div></div>`;
const detail=rows=>`<dl class="detail">${rows.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl>`;
const field=(label,id,type='text',value='',hint='',required=false)=>`<label class="field" for="${id}">${label}${required?' *':''}<input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${required?'required':''}>${hint?`<small>${hint}</small>`:''}</label>`;
const select=(label,id,options)=>`<label class="field" for="${id}">${label}<select id="${id}" name="${id}">${options.map(o=>`<option>${o}</option>`).join('')}</select></label>`;
const area=(label,id,value='',required=false)=>`<label class="field" for="${id}">${label}${required?' *':''}<textarea id="${id}" name="${id}" ${required?'required':''}>${esc(value)}</textarea></label>`;
const form=(body,action='preview',label='Xem trước thay đổi')=>`<form data-form="${action}">${body}<div class="form-actions">${btn('Hủy','cancel')}<button class="btn primary" type="submit">${label}${ico('arrow-right')}</button></div></form>`;
const tabs=(items)=>`<div class="tabs" role="group" aria-label="Nội dung">${items.map((s,i)=>`<button data-tab="${s[0]}" class="${i?'':'active'}" aria-pressed="${!i}">${s[1]}</button>`).join('')}</div>`;
const table=(heads,rows)=>`<div class="table-scroll" tabindex="0" role="region" aria-label="Bảng dữ liệu, cuộn ngang nếu cần"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr data-row>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const filters=(label='Tìm theo mã hoặc tên…',opts=['Tất cả trạng thái','Đang xử lý','Chờ phản hồi','Đã giải quyết'])=>`<div class="filters"><label class="sr-only" for="list-search">Tìm trong danh sách</label><input id="list-search" data-search placeholder="${label}" type="search"><label class="sr-only" for="list-filter">Lọc trạng thái</label><select id="list-filter" data-list-filter>${opts.map(o=>`<option>${o}</option>`).join('')}</select>${btn('Bộ lọc chi tiết','filters','','filter')}</div><p class="sr-only" id="filter-status" role="status" aria-live="polite"></p>`;
const listLine=(icon,title,text,action='')=>`<div class="line"><span class="tile">${ico(icon)}</span><div class="grow"><strong>${title}</strong><p>${text}</p></div>${action}</div>`;
const stat=(label,value,note)=>`<div class="panel stat"><p>${label}</p><div class="value">${value}</div><p>${note}</p></div>`;
const ticketRows=[
 ['TKT-000126','Cài đặt VPN cho laptop làm việc','Đang xử lý','blue','Bình','P2','Sắp tới hạn'],
 ['TKT-000125','Không mở được phần mềm kế toán','Chờ phản hồi','amber','Bình','P3','Đang tạm dừng'],
 ['TKT-000121','Máy in không kết nối được với laptop','Đã giải quyết','green','Chi','P3','Đã dừng'],
 ['TKT-000123','Cấp tài khoản cho nhân sự mới','Mới tiếp nhận','','Chưa phân công','P3','Trong hạn']
];
function ticketTable(mine=false){const rows=mine?ticketRows.filter(t=>t[0]!=='TKT-000123'):ticketRows;return table(['Yêu cầu','Trạng thái',...(mine?[]:['Phụ trách']),'Ưu tiên','SLA'],rows.map(t=>[`<span class="code">${t[0]}</span><a class="row-title" href="${urlFor(t[0]==='TKT-000121'?'ticket-result':t[0]==='TKT-000125'?'ticket-requester':t[0]==='TKT-000123'?'provision':mine?'ticket-active':'ticket-it')}">${t[1]}</a>`,pill(t[2],t[3]),...(mine?[]:[t[4]]),pill(t[5]),`<span class="${t[6]==='Sắp tới hạn'?'error-text':'muted'}">${t[6]}</span>`]));}
function ticketList(){return box('Hàng chờ hỗ trợ',filters()+ticketTable()+`<div class="panel-foot"><span>4 yêu cầu mẫu · Toàn phòng IT</span><span>Trang 1 / 1</span></div>`,'Phân biệt trạng thái tiếp nhận và phản hồi đầu tiên',link('Tạo yêu cầu','create','primary'));}
function createTicket(){return `<div class="grid"><div class="panel pad">${form(`<div class="two">${select('Loại yêu cầu','request-type',['Yêu cầu dịch vụ','Sự cố'])}${select('Danh mục','category',['Mạng & kết nối','Thiết bị','Phần mềm','Tài khoản'])}</div>${field('Tiêu đề','subject','text','','Mô tả ngắn vấn đề cần IT hỗ trợ.',true)}${area('Mô tả','description','',true)}<div class="two">${select('Mức ảnh hưởng','impact',['Cá nhân','Một nhóm','Nhiều phòng ban'])}${select('Mức khẩn cấp','urgency',['Bình thường','Cần sớm','Gián đoạn công việc'])}</div>${select('Thiết bị liên quan','asset-select',['Không liên kết thiết bị','LT-001 · Dell Latitude 5440'])}${field('Tệp đính kèm (minh họa)','files','file','','Tối đa theo chính sách; chỉ đính kèm dữ liệu được phép chia sẻ.')}<div class="banner"><div>Nhóm tiếp nhận do cấu hình hệ thống xác định. Bạn không chọn kỹ thuật viên hoặc tự đặt SLA.</div></div>`,'ticket-create','Xem trước yêu cầu')}</div><div class="stack">${box('Trước khi gửi',`<div class="pad"><p class="small muted">Cho IT biết vấn đề bắt đầu khi nào, có thông báo lỗi gì và ảnh hưởng đến ai.</p><div class="section-gap">${link('Tìm hướng dẫn','knowledge')}</div></div>`)}${box('Yêu cầu cấp tài khoản',`<div class="pad"><p class="small muted">Ghi rõ nhân sự, phòng ban, ngày bắt đầu và quyền cần cấp. Không ghi mật khẩu vào yêu cầu.</p></div>`)}</div></div>`;}
function ticketDetail(mode){const own=mode==='requester',admin=mode==='admin';return `${banner(own?'IT đang chờ phản hồi của bạn':admin?'Xác minh trước khi cấp quyền':'Bạn đang phụ trách yêu cầu này',own?'Gửi ảnh thông báo lỗi để IT tiếp tục xử lý.':admin?'Yêu cầu không tự tạo tài khoản hoặc chuyển trạng thái ticket.':'Cập nhật kết quả thực hiện ở công việc; trao đổi công khai tại ticket.',own?'amber':'')}<div class="grid"><div class="stack">${box(admin?'Cấp tài khoản cho nhân sự mới':own?'Không mở được phần mềm kế toán':'Cài đặt VPN cho laptop làm việc',`<div class="pad"><span class="code">${admin?'TKT-000123':own?'TKT-000125':'TKT-000126'}</span><div class="actions">${pill(own?'Chờ phản hồi':admin?'Mới tiếp nhận':'Đang xử lý',own?'amber':'blue')}${pill(own||admin?'P3':'P2')}</div><p class="section-gap small">${admin?'Đề nghị tạo tài khoản công việc cho nhân sự mới thuộc phòng Kế toán, bắt đầu ngày 12/11. Vai trò mặc định Requester.':'Không truy cập được dịch vụ nội bộ từ laptop. Đã thử kết nối lại mạng và khởi động lại thiết bị.'}</p></div>`)}${admin?box('Thực hiện cấp tài khoản',`<div class="pad">${detail([['Người yêu cầu','Đặng Ngọc Mai · Phòng Nhân sự'],['Nhân sự cần cấp','Nguyễn Văn Nam · Kế toán'],['Vai trò đề nghị','Requester']])}<label class="check"><input type="checkbox" id="verified">Đã xác minh người yêu cầu và phạm vi cấp quyền</label>${link('Mở form tạo người dùng','user-create','primary')}<p class="small muted section-gap">Form độc lập; không chuyển dữ liệu cá nhân qua URL, không tự đóng ticket.</p></div>`):''}${box('Trao đổi',`${tabs(own?[['public','Trao đổi công khai'],['timeline','Lịch sử']]:[['public','Trao đổi công khai'],['internal','Ghi chú nội bộ'],['timeline','Lịch sử']])}<div id="conversation"><div class="message"><span class="avatar">PL</span><div><strong>Nguyễn Phương Lan</strong><small> · Người yêu cầu · 09:15</small><p>Tôi đã thử lại nhưng vẫn chưa đăng nhập được. Nhờ IT kiểm tra giúp.</p></div></div><div class="message"><span class="avatar">QB</span><div><strong>Trần Quốc Bình</strong><small> · IT Support · 09:35</small><p>Chị gửi giúp ảnh thông báo lỗi sau khi đăng nhập. IT sẽ kiểm tra tiếp từ thông tin này.</p></div></div></div><div class="composer"><form data-form="reply"><input type="hidden" name="audience" value="public"><label class="field" for="reply">${own?'Phản hồi cho IT':'Nội dung công khai'}<textarea id="reply" required placeholder="Viết nội dung trao đổi…"></textarea></label><div class="actions"><button class="btn primary" type="submit">Xem trước phản hồi</button>${btn('Đính kèm','attachment','','paperclip')}${link('Mở AI Workspace',own?'ai-requester':'ai-tech','purple')}</div></form></div>`)}${!own?box('Công việc thực hiện',listLine('toolbox','T07 · Cài đặt và kiểm tra VPN','Đang thực hiện · Còn 60 phút · Hạn 11:30',link('Xem task','progress'))):box('Tiến độ hỗ trợ công khai',`<div class="pad"><p class="small muted">IT đã tiếp nhận yêu cầu và đang chờ bạn cung cấp thông tin. Không hiển thị phân bổ nhân sự hoặc ghi chú nội bộ.</p></div>`)}</div><aside class="stack">${box('Thông tin yêu cầu',`<div class="pad">${detail([['Người gửi',admin?'Đặng Ngọc Mai':'Nguyễn Phương Lan'],['Phòng ban',admin?'Nhân sự':'Kế toán'],['Nhóm','IT Support'],['Phụ trách',admin?'Chưa phân công':'Trần Quốc Bình'],['Danh mục',admin?'Tài khoản':'Phần mềm'],['Thiết bị',own?'LT-001 · Thiết bị của tôi':'LT-001 · Theo quyền truy cập']])}</div>`)}${box('Cam kết hỗ trợ',`<div class="pad">${detail([['Phản hồi đầu','Đã phản hồi · 20 phút'],['Giải quyết',own?'Đang tạm dừng':'Còn 1 giờ 30 phút'],['Đồng hồ','24/7 · Theo snapshot']])}<p class="small muted section-gap">Chuyển nhóm hoặc đổi ưu tiên không xóa thời gian đã dùng và lịch sử vi phạm.</p></div>`)}${box('Thao tác',`<div class="pad stack">${own?link('Xem ticket đã có kết quả','ticket-result'):admin?link('Phân công xử lý','assign'):link('Thay đổi trạng thái','transition')}${admin?link('Đổi người phụ trách','assign'):''}${admin?link('Đổi ưu tiên','priority'):''}</div>`)}</aside></div>`;}
function assign(){return dialogStage('Phân công yêu cầu',`<p class="small muted">TKT-000126 · Hiện tại: IT Support / Trần Quốc Bình</p><div class="section-gap">${form(`${select('Nhóm tiếp nhận','assign-team',['IT Support','Infrastructure'])}${select('Người thực hiện','assign-user',['Trần Quốc Bình · Thành viên nhóm','Lê Ngọc Chi · Thành viên nhóm'])}${area('Lý do phân công / chuyển nhóm','assign-reason','',true)}${banner('Kiểm tra lại khi thực hiện','Nếu người phụ trách hoặc thành viên nhóm đã thay đổi, tải lại dữ liệu trước khi xác nhận. Ticket đang xử lý cần người thay thế hợp lệ.','amber')}`,'assignment','Xem trước phân công')}</div>`);}
function transition(){return dialogStage('Cập nhật trạng thái ticket',`${banner('Trạng thái hiện tại: Đang xử lý','Đề xuất giải quyết là Resolved; người yêu cầu xác nhận mới chuyển Closed.')}<div class="two">${btn('Chờ phản hồi','wait')}${btn('Đề xuất giải quyết','resolve')}${btn('Xem nhánh tiếp nhận / bắt đầu','start')}${btn('Xem nhánh mở lại / hủy','reopen')}</div><div class="section-gap">${form(`${select('Thao tác đang review','transition-type',['Đề xuất giải quyết','Chờ phản hồi'])}${area('Kết quả hoặc câu hỏi công khai','transition-body','Đã cài lại cấu hình VPN. Nhờ bạn kết nối và kiểm tra truy cập dịch vụ nội bộ.',true)}${field('Các bước kiểm tra','test-steps','text','Kết nối VPN → mở dịch vụ nội bộ')}`,'transition','Xem trước nội dung công khai')}</div>`);}
function priority(){return dialogStage('Thay đổi ưu tiên',`${detail([['Yêu cầu','TKT-000126'],['Hiện tại','P3 · Thời gian đã dùng được giữ lại']])}<div class="section-gap">${form(`${select('Ưu tiên mới','new-priority',['P2','P1','P3','P4'])}${area('Lý do thay đổi','priority-reason','',true)}${banner('SLA không bắt đầu lại','Giữ lịch sử vi phạm; phần ngân sách còn lại được tính theo thời gian đã dùng.','amber')}`,'priority')}</div>`);}
function dialogStage(title,body){return `<div class="panel pad" style="max-width:780px;margin:auto"><div class="actions" style="justify-content:space-between;margin-bottom:22px"><h2>${title}</h2>${link('Về ticket','ticket-it')}</div>${body}</div>`;}
const taskData=[['T02','Kiểm tra laptop trong kho','Đang thực hiện','Bình',60,'10:00–11:00'],['T07','Cài đặt và kiểm tra VPN','Đang thực hiện','Bình',60,'11:00–12:00'],['T03','Cài phần mềm cho nhân sự mới','Sẵn sàng','Minh',180,'11:00–14:00'],['T09','Kiểm tra màn hình Kế toán','Sẵn sàng','Bình',60,'14:00–15:00'],['T11','Kiểm tra truy cập phần mềm','Bị chặn','Chi',120,'Chờ phụ thuộc']];
function taskCard(t){const tone=t[2]==='Bị chặn'?'blocked':t[2]==='Sẵn sàng'?'success':'active';return `<article class="task"><span class="code">${t[0]} · ${t[0]==='T07'?'TKT-000126':'TKT-000124'}</span><h3>${t[1]}</h3><div class="actions"><span class="pill" data-state-tone="${tone}">${t[2]}</span>${t[0]==='T03'?'<span class="pill" data-state-tone="locked">Đang khóa</span>':''}</div><p class="section-gap">${t[3]} · Còn ${t[4]} phút</p><p>${t[5]}</p>${btn('Xem công việc','task-'+t[0])}</article>`;}
function work(mine=false){const rows=mine?taskData.filter(t=>t[3]==='Bình'):taskData;return `${banner(mine?'Việc cần tiếp tục: T07 · Kiểm tra VPN':'5 task chưa hoàn tất trong mẫu review','Ticket và task có vòng đời riêng; hoàn thành task không tự đóng ticket.')}<div class="actions" style="margin-bottom:20px">${link('Xem kế hoạch','plan')}${btn('Bộ lọc công việc','work-filter','','filter')}${pill('Không kéo thả thay đổi trạng thái')}</div><div class="kanban">${['Sẵn sàng','Đang thực hiện','Bị chặn'].map(st=>`<section class="lane"><h2>${st} · ${rows.filter(t=>t[2]===st).length}</h2>${rows.filter(t=>t[2]===st).map(taskCard).join('')||'<p class="small muted">Chưa có công việc ở trạng thái này.</p>'}</section>`).join('')}</div><div class="panel pad section-gap"><h2>Vòng đời công việc</h2><p class="small muted section-gap">To Do → Ready → In Progress → Done; Blocked và Cancelled có lý do. Mẫu DEMO dùng bản dịch hiển thị; API giữ các giá trị trạng thái chuẩn.</p></div>`;}
function plan(){return `${banner('Kế hoạch onboarding · Phiên bản 3 đang có hiệu lực','Phụ thuộc và khóa thủ công phải được kiểm tra lại trước khi giao việc.')}<div class="grid"><div class="stack">${box('Luồng phụ thuộc',`<div class="pad"><div class="dag"><div class="node"><strong>T01 · Đã hoàn tất</strong>Chuẩn bị hồ sơ</div><span>${ico('arrow-right')}</span><div class="node"><strong>T02 · Đang thực hiện</strong>Kiểm tra thiết bị</div><span>${ico('arrow-right')}</span><div class="node locked"><strong>T03 · Đang khóa</strong>Cài phần mềm</div></div><p class="small muted section-gap">Danh sách tương đương: T02 phụ thuộc T01; T03 phụ thuộc T02. Chưa thể bắt đầu T03 khi T02 chưa hoàn tất.</p></div>`)}${box('Task trong kế hoạch',table(['Công việc','Phụ thuộc','Thực hiện','Còn lại'],[['T01 · Chuẩn bị hồ sơ','—','An','0 phút'],['T02 · Kiểm tra laptop','T01','Bình','60 phút'],[`${btn('T03 · Cài phần mềm','task-T03')}`,'T02',`Minh ${pill('Khóa','amber')}`,'180 phút']]))}</div><aside class="stack">${box('Thông tin kế hoạch',`<div class="pad">${detail([['Ticket','TKT-000124'],['Phiên bản','v3 · Đang hiệu lực'],['Hạn bàn giao','09/11 · 16:00'],['Hạn T03','09/11 · 14:00'],['Lịch sử','v1, v2 · Chỉ đọc']])}</div>`)}${box('Ngoại lệ',`<div class="pad"><p class="small muted">Minh vắng 10:00–14:00. Task T03 đang khóa; chưa tự đổi người thực hiện.</p><div class="section-gap">${link('Xem đề xuất trong Workspace','ai-exception','purple')}</div></div>`)}</aside></div>`;}
function progress(){return `<div class="grid"><div class="stack">${banner('T07 · Cài đặt và kiểm tra kết nối VPN','Khung dự kiến 11:00–12:00 vượt hạn 11:30. Cần rà soát kế hoạch.','amber')}<div class="panel pad">${form(`${detail([['Người thực hiện','Trần Quốc Bình'],['Trạng thái','In Progress'],['Phụ thuộc','Đã đủ'],['Hạn task','09/11 · 11:30']])}<div class="two section-gap">${select('Trạng thái cập nhật','task-status',['In Progress','Blocked','Done'])}${field('Thời gian còn lại (phút)','remaining','number','60','Done yêu cầu remaining = 0.',true)}</div>${area('Kết quả hoặc vướng mắc','result','Đã cài client VPN. Cần kiểm tra truy cập và ghi nhận kết quả.',true)}${banner('Hoàn tất có bằng chứng','Ghi kết quả và thời gian còn lại bằng 0 trước khi đề nghị Done. Ticket được xử lý riêng.')}`,'task-progress','Xem trước cập nhật')}</div></div><aside class="stack">${box('Liên kết',`<div class="pad stack">${link('Mở ticket liên quan','ticket-it')}${link('Xem kế hoạch','plan')}</div>`)}${box('Lịch sử thực hiện',listLine('history','09:40 · Cập nhật remaining','Bình · 90 → 60 phút')+listLine('check-circle','09:10 · Bắt đầu thực hiện','Trạng thái Ready → In Progress'))}</aside></div>`;}
