function userCreate(){return `<div class="grid"><div class="panel pad">${form(`${field('Họ và tên','user-name','text','','',true)}${field('Email công việc','user-email','email','','Dùng địa chỉ doanh nghiệp.',true)}<div class="two">${select('Phòng ban','user-dept',['Kế toán','IT','Nhân sự','Kinh doanh'])}${select('Vai trò','user-role',['Requester','Technician','IT_MANAGER','Admin'])}</div>${field('Mật khẩu ban đầu','initial-password','password','','Bàn giao theo kênh doanh nghiệp; không gửi vào ticket hoặc chat.',true)}${banner('Vai trò mặc định: Requester','Cấp quyền IT cần phê duyệt phù hợp. Không tự chuyển trạng thái ticket sau khi tạo tài khoản.','amber')}`,'user-create','Xem trước thông tin tài khoản')}</div><aside>${box('Nguyên tắc bàn giao',`<div class="pad"><p class="small muted">Bản xem trước không hiển thị lại mật khẩu. Không khẳng định đã gửi email. Kết quả tạo tài khoản thật cần được Admin ghi nhận riêng.</p></div>`)}</aside></div>`;}
function organization(kind){const cfg={departments:['Phòng ban',['Tên','Mã','Trạng thái'],[['Kế toán','ACC',pill('Đang hoạt động','green')],['Nhân sự','HR',pill('Đang hoạt động','green')],['IT','IT',pill('Đang hoạt động','green')]]],teams:['Nhóm hỗ trợ',['Nhóm','Thành viên','Phạm vi'],[['IT Support','Bình, Chi, Minh','Thiết bị · Mạng · Phần mềm'],['Infrastructure','Nhóm chuyên trách','Hạ tầng']]],categories:['Danh mục',['Tên','Nhóm tiếp nhận mặc định','Trạng thái'],[['Thiết bị','IT Support',pill('Đang hoạt động','green')],['Mạng & kết nối','IT Support',pill('Đang hoạt động','green')],['Tài khoản','IT Support',pill('Đang hoạt động','green')]]]}[kind];return `<div class="grid"><div>${box(cfg[0],table(cfg[1],cfg[2]),'Cấu hình tổ chức không tự cấp quyền đọc mọi dữ liệu',btn('Thêm / chỉnh sửa','edit-'+kind,'primary','plus'))}${kind==='teams'?box('Thành viên · IT Support',listLine('user','Trần Quốc Bình','Technician · Đang hoạt động',btn('Review thành viên','team-member'))+listLine('user','Lê Ngọc Chi','Technician · Đang hoạt động',btn('Review thành viên','team-member'))):''}</div><aside>${box('Kiểm tra trước khi lưu',`<div class="pad"><p class="small muted">Không xóa lịch sử. Thay đổi thành viên phải xét ticket/task đang được phụ trách; không để In Progress/Pending mất người hợp lệ.</p><div class="section-gap">${btn('Xem nhánh chuyển giao','handover')}</div></div>`)}</aside></div>`;}
function sla(){return `<div class="grid"><div class="panel pad"><h2>Ngân sách SLA mặc định · v3</h2><p class="subtitle">Hai đồng hồ độc lập: phản hồi đầu tiên và giải quyết.</p><div class="section-gap">${form(`${table(['Ưu tiên','Phản hồi (phút)','Giải quyết (phút)'],[['P1','15','120'],['P2','30','240'],['P3','60','480'],['P4','240','1440']])}<div class="two section-gap">${select('Ưu tiên đang chỉnh','sla-priority',['P3','P1','P2','P4'])}${field('Phản hồi đầu (phút)','sla-response','number','60','Số phút lớn hơn 0.',true)}</div>${field('Giải quyết (phút)','sla-resolution','number','480','Số phút lớn hơn 0.',true)}${area('Lý do thay đổi','sla-reason','',true)}`,'sla','Xem trước phiên bản mới')}</div></div><aside class="stack">${banner('Chỉ áp dụng cho ticket mới','Ticket cũ giữ snapshot SLA. Pending chỉ tạm dừng giải quyết theo quy tắc; phản hồi đầu chỉ tính từ nội dung IT công khai có ý nghĩa.','amber')}${box('Lịch sử cấu hình',listLine('history','v3 · Hiện hành','Admin · 09/11/2026')+listLine('history','v2 · Chỉ đọc','Admin · 01/11/2026'))}</aside></div>`;}
function aiSettings(){return `<div class="grid"><div class="panel pad">${form(`${banner('Chưa kết nối provider','Workspace vẫn cho phép xem trạng thái và mở form thủ công theo quyền.','amber')}${select('Khả năng sử dụng trợ lý','ai-availability',['Chưa cấu hình','Bật khi có cấu hình hợp lệ','Tạm ngừng'])}${field('Tên cấu hình','provider-label','text','Trợ lý nội bộ')}${field('Model hiển thị','model-label','text','','Chỉ nhãn thiết kế; không xác nhận model/provider đang hoạt động.')}<div class="banner"><div>Bí mật được cấu hình ngoài chat qua cơ chế quản lý secret của hệ thống. Form review này không nhận API key.</div></div>`,'ai-settings')}</div><aside>${box('Phân biệt trách nhiệm',`<div class="pad">${detail([['Admin','Khả năng dùng trợ lý và cấu hình hệ thống'],['IT Manager','Chính sách điều phối trong phạm vi được cấp'],['Dữ liệu','Không truy cập hội thoại người khác'],['Usage / cost','Chưa có nguồn · Không hiển thị 0 giả']])}</div>`)}</aside></div>`;}
