function states(){return `<div class="two"><section class="panel pad" aria-label="Minh họa đang tải"><h2>Đang tải dữ liệu</h2><p class="small muted section-gap" role="status">Đang tải yêu cầu…</p><div class="section-gap" aria-hidden="true"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div></section><section class="panel empty"><span class="tile">${ico('inbox')}</span><h2>Bạn chưa có yêu cầu nào</h2><p>Tạo yêu cầu đầu tiên khi cần IT hỗ trợ.</p>${link('Tạo yêu cầu','create','primary')}</section><section class="panel empty"><span class="tile">${ico('search')}</span><h2>Không có kết quả phù hợp</h2><p>Thử từ khóa khác hoặc bỏ bớt điều kiện lọc.</p>${btn('Xóa bộ lọc','clear-filters')}</section><section class="panel empty"><span class="tile">${ico('alert')}</span><h2>Chưa tải được dữ liệu</h2><p>Kiểm tra kết nối rồi thử lại. Nội dung bạn đang soạn được giữ trong phiên hiện tại.</p>${btn('Thử lại','retry','primary')}</section></div><div class="section-gap">${banner('Dữ liệu đã thay đổi','Tải lại phiên bản hiện tại và kiểm tra trước khi gửi lại. Không tự ghi đè thay đổi của người khác.','amber')}${btn('Xem nhánh xung đột / phiên hết hạn','conflict')}</div>`;}


